package site.cadera.arunika.dungeon.paper;

import java.util.*;
import java.util.function.Consumer;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.entity.Player;
import org.bukkit.command.CommandSender;
import site.cadera.arunika.dungeon.battle.ArenaAccessPolicy;
import org.bukkit.event.*;
import org.bukkit.event.block.Action;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.Plugin;
import net.kyori.adventure.text.Component;
import site.cadera.arunika.dungeon.config.SmartConfiguration.Gateway;
import site.cadera.arunika.dungeon.core.DungeonGatewayApi.*;

/** Native inventory UI works via normal Geyser inventory translation; no proprietary form dependency. */
final class PaperGateway implements Listener {
 private final ArunikaDungeonPlugin plugin; private final Gateway cfg; private final WaystoneBridge bridge;
 private final Map<UUID,Menu> menus=new HashMap<>();
 private static final int PAGE=36;
 private record Status(List<SharedFloorStatus> shared,List<PrivatePartyStatus> parties,List<site.cadera.arunika.dungeon.core.SessionRegistry.Session> sessions,List<site.cadera.arunika.dungeon.battle.BattleEngine.View> battles){}
 private Status cached;
 private Status status(){return cached!=null?cached:new Status(plugin.sharedStatus(),plugin.privateStatus(),plugin.gatewaySessions(),plugin.gatewayBattles());}
 private enum Screen{HOME,FLOORS,SHARED,PRIVATE_DETAIL,PARTY,INVITE,RETURN}
 private static final class Menu implements InventoryHolder {
  final UUID owner,stone; final Screen screen; final boolean priv; final String floor; final int page;
  boolean clickPending;final Map<Integer,Consumer<Player>> actions=new HashMap<>(); final BitSet written=new BitSet(54); final Inventory inventory;
  Menu(Player p,UUID stone,Screen screen,boolean priv,String floor,int page){owner=p.getUniqueId();this.stone=stone;this.screen=screen;this.priv=priv;this.floor=floor;this.page=page;inventory=Bukkit.createInventory(this,54,Component.text("Arunika | "+switch(screen){case HOME->"Dungeon Hub";case FLOORS->priv?"Private Floors":"Shared Floors";case SHARED->"Shared Participants";case PRIVATE_DETAIL->"Private Participants";case PARTY->"Private Party";case INVITE->"Invite Players";case RETURN->"Return to Hub";}));}
  @Override public Inventory getInventory(){return inventory;}
 }
 PaperGateway(ArunikaDungeonPlugin plugin,Gateway cfg)throws ReflectiveOperationException{this.plugin=plugin;this.cfg=cfg;Plugin ws=Bukkit.getPluginManager().getPlugin("CdrWaystone");if(ws==null||!ws.isEnabled())throw new IllegalStateException("CdrWaystone missing");bridge=new WaystoneBridge(ws);Object hubStone=bridge.stone(cfg.hubId());if(!bridge.dedicated(hubStone))throw new IllegalStateException("Hub must be a permanent admin Waystone, hidden from network and not legacy-bound");var anchor=bridge.location(hubStone);if(anchor==null||anchor.getWorld()==null||!ArenaAccessPolicy.near(PaperBattlePort.point(anchor.clone().add(.5,.5,.5)),cfg.hub(),cfg.radius()))throw new IllegalStateException("Hub exit must be in the same world and within interaction radius of its registered Waystone");for(var e:cfg.returns().entrySet()){Object stone=bridge.stone(e.getKey());if(!bridge.dedicated(stone)||!plugin.gatewayStoneInArena(e.getValue(),bridge.location(stone)))throw new IllegalStateException("Invalid return stone: "+e.getKey());}}
 boolean atHub(Player p){try{if(!p.hasPermission("arunika.dungeon.gateway.test")||!bridge.allowed(p,bridge.stone(cfg.hubId()),cfg.radius(),true))return false;var hub=PaperBattlePort.location(cfg.hub());return p.getWorld().equals(hub.getWorld())&&p.getLocation().distanceSquared(hub)<=cfg.radius()*cfg.radius();}catch(RuntimeException|LinkageError e){return false;}}
 private boolean bound(UUID id){return cfg.hubId().equals(id)||cfg.returns().containsKey(id);}
 @EventHandler(priority=EventPriority.NORMAL,ignoreCancelled=true) public void block(PlayerInteractEvent e){if(e.getAction()!=Action.RIGHT_CLICK_BLOCK||e.getHand()!=EquipmentSlot.HAND||e.getClickedBlock()==null||!bridge.available())return;try{Object stone=bridge.stone(e.getClickedBlock());if(stone==null||!bound(bridge.id(stone)))return;e.setCancelled(true);route(e.getPlayer(),stone);}catch(RuntimeException|LinkageError err){e.getPlayer().sendMessage("Dungeon Waystone unavailable.");}}
 @EventHandler(priority=EventPriority.NORMAL,ignoreCancelled=true) public void plainEntity(PlayerInteractEntityEvent e){if(!(e instanceof PlayerInteractAtEntityEvent))entityClick(e);}
 @EventHandler(priority=EventPriority.NORMAL,ignoreCancelled=true) public void entity(PlayerInteractAtEntityEvent e){entityClick(e);}
 private void entityClick(PlayerInteractEntityEvent e){if(e.getHand()!=EquipmentSlot.HAND||!bridge.available())return;try{Object stone=bridge.stone(e.getRightClicked());if(stone==null||!bound(bridge.id(stone)))return;e.setCancelled(true);route(e.getPlayer(),stone);}catch(RuntimeException|LinkageError err){e.getPlayer().sendMessage("Dungeon Waystone unavailable.");}}
 void openTarget(Player p){try{Block block=p.getTargetBlockExact((int)Math.ceil(cfg.radius()));Object stone=block==null?null:bridge.stone(block);if(stone==null||!bound(bridge.id(stone)))throw new IllegalStateException("Look at the bound Waystone anchor");route(p,stone);}catch(RuntimeException|LinkageError e){p.sendMessage("Gateway unavailable: "+e.getMessage());}}
 private void route(Player p,Object stone){UUID id=bridge.id(stone);Menu existing=menus.get(p.getUniqueId());if(existing!=null&&existing.stone.equals(id)&&p.getOpenInventory().getTopInventory()==existing.inventory&&valid(p,existing))return;if(!plugin.gatewayUsable()||!p.hasPermission("arunika.dungeon.gateway.test")||!bridge.allowed(p,stone,cfg.radius(),cfg.hubId().equals(id))){p.sendMessage("Dungeon gateway unavailable or access denied.");return;}if(cfg.hubId().equals(id)){if(!atHub(p)){p.sendMessage("Stand at the Dungeon Hub.");return;}open(p,id,Screen.HOME,false,"",0);}else if(plugin.gatewayReturnEligible(p,cfg.returns().get(id),bridge.location(stone)))open(p,id,Screen.RETURN,false,cfg.returns().get(id),0);else p.sendMessage("Return Waystone requires your own active arena session.");}
 static void check(ArunikaDungeonPlugin plugin,CommandSender sender){try{Plugin ws=Bukkit.getPluginManager().getPlugin("CdrWaystone");if(ws==null||!ws.isEnabled())throw new IllegalStateException("CdrWaystone not enabled");WaystoneBridge b=new WaystoneBridge(ws);sender.sendMessage("Waystone public ABI: OK | "+ws.getDescription().getVersion());Plugin bed=Bukkit.getPluginManager().getPlugin("CdrWaystoneBedrock");sender.sendMessage("Bedrock renderer: "+(bed==null?"missing":bed.getDescription().getVersion()+" / enabled="+bed.isEnabled())+" | native anchor + target fallback; proxy clicks require client test");var cfg=plugin.adminSnapshot().gateway();sender.sendMessage("Gateway config enabled="+cfg.enabled()+" | hub UUID="+cfg.hubId()+" | return bindings="+cfg.returns().size());if(cfg.hubId()!=null){Object s=b.stone(cfg.hubId());sender.sendMessage("Hub dedicated="+b.dedicated(s)+(s==null?"":" | anchor="+b.location(s)));}for(var e:cfg.returns().entrySet()){Object s=b.stone(e.getKey());sender.sendMessage(e.getValue()+": "+e.getKey()+" | valid="+(b.dedicated(s)&&plugin.gatewayStoneInArena(e.getValue(),b.location(s))));}}catch(Exception|LinkageError e){sender.sendMessage("Waystone diagnostic failed: "+e);}}
 static void inspect(ArunikaDungeonPlugin plugin,Player p){try{Plugin ws=Bukkit.getPluginManager().getPlugin("CdrWaystone");if(ws==null||!ws.isEnabled())throw new IllegalStateException("CdrWaystone missing");WaystoneBridge b=new WaystoneBridge(ws);Block block=p.getTargetBlockExact(8);Object s=block==null?null:b.stone(block);if(s==null)throw new IllegalStateException("Look at a registered Waystone anchor block");p.sendMessage("Waystone UUID: "+b.id(s)+" | permanent admin: "+b.official(s)+" | hidden and unbound: "+b.dedicated(s)+" | "+b.location(s));}catch(Exception|LinkageError e){p.sendMessage("Waystone inspect: "+e.getMessage());}}
 void close(){HandlerList.unregisterAll(this);for(var m:new ArrayList<>(menus.values())){Player p=Bukkit.getPlayer(m.owner);if(p!=null&&p.getOpenInventory().getTopInventory()==m.inventory)p.closeInventory();}menus.clear();}
 private boolean valid(Player p,Menu m){try{return plugin.gatewayUsable()&&p.getUniqueId().equals(m.owner)&&p.hasPermission("arunika.dungeon.gateway.test")&&bound(m.stone)&&(m.screen==Screen.RETURN?bridge.allowed(p,bridge.stone(m.stone),cfg.radius(),false)&&plugin.gatewayReturnEligible(p,cfg.returns().get(m.stone),bridge.location(bridge.stone(m.stone))):atHub(p));}catch(RuntimeException|LinkageError e){return false;}}
 private void open(Player p,UUID id,Screen s,boolean priv,String floor,int page){Menu m=new Menu(p,id,s,priv,floor,Math.max(0,page));if(!valid(p,m))return;render(p,m);p.openInventory(m.inventory);menus.put(p.getUniqueId(),m);}
 private void go(Player p,Menu m,Screen s,boolean priv,String floor,int page){open(p,m.stone,s,priv,floor,page);}
 private void button(Menu m,int slot,Material mat,String name,List<String> lore,Consumer<Player> action){ItemStack item=new ItemStack(mat);var meta=item.getItemMeta();meta.displayName(GuiTheme.name(name,mat));meta.lore(lore.stream().map(GuiTheme::lore).toList());item.setItemMeta(meta);m.written.set(slot);if(!item.equals(m.inventory.getItem(slot)))m.inventory.setItem(slot,item);if(action!=null)m.actions.put(slot,action);}
 private void button(Menu m,int slot,Material mat,String name,Consumer<Player> action){button(m,slot,mat,name,List.of(),action);}
 private String name(UUID id){Player p=Bukkit.getPlayer(id);return p==null?id.toString():p.getName();}
 private List<String> names(Collection<UUID> ids){List<String> n=ids.stream().limit(5).map(this::name).toList();var out=new ArrayList<>(n);if(ids.size()>5)out.add("+"+(ids.size()-5)+" more");return out;}
 private Optional<PrivatePartyStatus> party(Player p){return status().parties().stream().filter(v->v.members().contains(p.getUniqueId())).findFirst();}
 private void pageButtons(Menu m,int size){if(m.page>0)button(m,45,Material.ARROW,"Previous",p->go(p,m,m.screen,m.priv,m.floor,m.page-1));if((m.page+1)*PAGE<size)button(m,53,Material.ARROW,"Next",p->go(p,m,m.screen,m.priv,m.floor,m.page+1));}
 private void render(Player p,Menu m){m.written.clear();m.actions.clear();switch(m.screen){
  case HOME->{button(m,20,Material.EMERALD,"Shared Dungeon",List.of("Free access","No dungeon participant cap"),q->go(q,m,Screen.FLOORS,false,"",0));button(m,24,Material.AMETHYST_SHARD,"Private Dungeon",List.of("1 Universal Ticket per party","1–5 players"),q->go(q,m,Screen.FLOORS,true,"",0));button(m,38,Material.PLAYER_HEAD,"My Private Party",q->go(q,m,Screen.PARTY,true,"",0));button(m,40,Material.LIME_DYE,"Accept invitation",q->{plugin.gatewayAction(q,true,"accept");go(q,m,Screen.PARTY,true,"",0);});button(m,42,Material.RED_DYE,"Decline invitation",q->{plugin.gatewayAction(q,true,"decline");q.closeInventory();});button(m,49,Material.BARRIER,"Leave Shared queue",q->{plugin.gatewayAction(q,false,"leave");q.closeInventory();});}
  case FLOORS->{var floors=plugin.floors();var statuses=new HashMap<String,SharedFloorStatus>();for(var v:status().shared())statuses.put(v.floor(),v);var parties=status().parties();var battles=status().sessions();int start=m.page*PAGE;for(int i=start;i<Math.min(start+PAGE,floors.size());i++){var f=floors.get(i);boolean available=plugin.gatewayFloor(f.id(),m.priv);List<String> lore=new ArrayList<>();if(!available)lore.add("Unavailable / not configured");else if(m.priv){var groups=parties.stream().filter(v->v.floor().equals(f.id())).toList();lore.add("1 Universal Dungeon Ticket");lore.add("Party waiting: "+groups.size());var runs=battles.stream().filter(v->v.floor().equals(f.id())&&v.mode()==site.cadera.arunika.dungeon.core.SessionRegistry.Mode.PRIVATE).toList();lore.add("Active private sessions: "+runs.size());lore.addAll(names(runs.stream().flatMap(v->v.participants().stream()).distinct().toList()));for(var g:groups.stream().limit(3).toList())lore.add(name(g.leader())+" | "+g.members().size()+" members");}else{var v=statuses.get(f.id());if(v!=null){lore.add(v.state()+" | "+v.seconds()+"s");lore.add("Queue: "+v.queued().size()+" | active: "+v.active().size());lore.addAll(names(v.active().isEmpty()?v.queued():v.active()));}}button(m,i-start,available?(m.priv?Material.AMETHYST_SHARD:Material.EMERALD):Material.GRAY_DYE,"Floor "+f.number()+" - "+f.name(),lore,available?q->{if(m.priv){go(q,m,Screen.PRIVATE_DETAIL,true,f.id(),0);}else go(q,m,Screen.SHARED,false,f.id(),0);}:null);}pageButtons(m,floors.size());button(m,49,Material.COMPASS,"Back",q->go(q,m,Screen.HOME,false,"",0));}
  case SHARED->{var opt=status().shared().stream().filter(v->v.floor().equals(m.floor)).findFirst();if(opt.isPresent()){var v=opt.get();List<UUID> ids=new ArrayList<>(v.active().stream().sorted().toList());for(UUID id:v.queued())if(!v.active().contains(id))ids.add(id);for(int i=m.page*PAGE;i<Math.min((m.page+1)*PAGE,ids.size());i++){UUID id=ids.get(i);button(m,i-m.page*PAGE,Material.PLAYER_HEAD,name(id),List.of(v.living().contains(id)?"Fighting":v.active().contains(id)?"Eliminated / active roster":"Queued"),null);}pageButtons(m,ids.size());var run=status().sessions().stream().filter(x->x.floor().equals(m.floor)&&x.mode()==site.cadera.arunika.dungeon.core.SessionRegistry.Mode.SHARED).findFirst();List<String> lore=new ArrayList<>(List.of("Queue: "+v.queued().size(),"Active: "+v.active().size()));run.ifPresent(r->status().battles().stream().filter(b->b.id().equals(r.id())).findFirst().ifPresent(b->lore.add(b.phase()+" | Wave "+b.wave()+"/"+b.waveCount())));button(m,40,Material.CLOCK,v.state()+" | "+v.seconds()+"s",lore,null);}button(m,38,Material.LIME_DYE,"Join queue",q->{plugin.gatewayAction(q,false,"join",m.floor);go(q,m,Screen.SHARED,false,m.floor,0);});button(m,42,Material.RED_DYE,"Leave queue",q->{plugin.gatewayAction(q,false,"leave");go(q,m,Screen.SHARED,false,m.floor,0);});button(m,49,Material.COMPASS,"Back",q->go(q,m,Screen.FLOORS,false,"",0));}
  case PRIVATE_DETAIL->{var ids=new LinkedHashMap<UUID,String>();for(var v:status().parties())if(v.floor().equals(m.floor))for(UUID id:v.members().stream().sorted().toList())ids.put(id,v.queued()?"Queued party":"Preparing party");for(var v:status().sessions())if(v.floor().equals(m.floor)&&v.mode()==site.cadera.arunika.dungeon.core.SessionRegistry.Mode.PRIVATE)for(UUID id:v.participants().stream().sorted().toList())ids.put(id,"Active session");var rows=new ArrayList<>(ids.entrySet());for(int i=m.page*PAGE;i<Math.min((m.page+1)*PAGE,rows.size());i++){var row=rows.get(i);button(m,i-m.page*PAGE,Material.PLAYER_HEAD,name(row.getKey()),List.of(row.getValue()),null);}pageButtons(m,rows.size());button(m,40,Material.AMETHYST_SHARD,"Create / My Party",List.of("1 ticket per session"),q->{if(party(q).isEmpty())plugin.gatewayAction(q,true,"create",m.floor);go(q,m,Screen.PARTY,true,m.floor,0);});button(m,49,Material.COMPASS,"Back",q->go(q,m,Screen.FLOORS,true,"",0));}
  case PARTY->{var opt=party(p);if(opt.isEmpty()){button(m,22,Material.PAPER,"No private party",q->go(q,m,Screen.FLOORS,true,"",0));}else{var v=opt.get();boolean leader=v.leader().equals(p.getUniqueId());int i=10;for(UUID id:v.members()){button(m,i++,Material.PLAYER_HEAD,name(id),List.of(id.equals(v.leader())?"Leader":"Member",v.ready().contains(id)?"Ready":"Not ready"),null);}button(m,22,Material.PAPER,"Floor: "+v.floor(),List.of(v.queued()?"Waiting for arena":"Preparing party",leader?"Hold a valid ticket before Start":"Leader pays"),null);button(m,28,Material.LIME_DYE,"Ready",q->{plugin.gatewayAction(q,true,"ready");go(q,m,Screen.PARTY,true,v.floor(),0);});button(m,29,Material.YELLOW_DYE,"Not ready",q->{plugin.gatewayAction(q,true,"unready");go(q,m,Screen.PARTY,true,v.floor(),0);});if(leader){button(m,30,Material.PLAYER_HEAD,"Invite player",q->go(q,m,Screen.INVITE,true,v.floor(),0));button(m,32,Material.EMERALD,"Start / Queue",q->{plugin.gatewayAction(q,true,"start");q.closeInventory();});button(m,33,Material.RED_DYE,"Cancel queue",q->{plugin.gatewayAction(q,true,"cancel");go(q,m,Screen.PARTY,true,v.floor(),0);});}button(m,34,Material.BARRIER,"Leave party",q->{plugin.gatewayAction(q,true,"leave");go(q,m,Screen.HOME,false,"",0);});}button(m,49,Material.COMPASS,"Back",q->go(q,m,Screen.HOME,false,"",0));button(m,50,Material.CLOCK,"Refresh",q->go(q,m,Screen.PARTY,true,m.floor,0));}
  case INVITE->{var candidates=Bukkit.getOnlinePlayers().stream().filter(q->!q.equals(p)&&q.hasPermission("arunika.dungeon.gateway.test")&&q.hasPermission("arunika.dungeon.private.test")).sorted(Comparator.comparing(Player::getName)).toList();for(int i=m.page*PAGE;i<Math.min((m.page+1)*PAGE,candidates.size());i++){UUID id=candidates.get(i).getUniqueId();button(m,i-m.page*PAGE,Material.PLAYER_HEAD,candidates.get(i).getName(),q->{Player target=Bukkit.getPlayer(id);if(target!=null)plugin.gatewayAction(q,true,"invite",target.getName());go(q,m,Screen.PARTY,true,m.floor,0);});}pageButtons(m,candidates.size());button(m,49,Material.COMPASS,"Back",q->go(q,m,Screen.PARTY,true,m.floor,0));}
  case RETURN->{button(m,22,Material.ENDER_PEARL,"Return to Dungeon Hub",List.of("Leave this battle permanently","No refund for voluntary exit"),q->{String[] a=m.floor.split("/",2);if(a.length==2&&plugin.gatewayReturn(q,a[0],a[1],bridge.location(bridge.stone(m.stone))))q.closeInventory();else q.sendMessage("Return refused: not a living participant of this arena, or exit unavailable.");});button(m,31,Material.BARRIER,"Cancel",Player::closeInventory);}
 }for(int slot=45;slot<54;slot++)if(!m.written.get(slot))button(m,slot,Material.BLACK_STAINED_GLASS_PANE," ",null);for(int slot=0;slot<54;slot++)if(!m.written.get(slot)&&m.inventory.getItem(slot)!=null)m.inventory.clear(slot);}
 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Menu m))return;boolean wasCancelled=e.isCancelled();e.setCancelled(true);if(wasCancelled)return;if(!(e.getWhoClicked() instanceof Player p)||menus.get(p.getUniqueId())!=m||!valid(p,m)){e.getWhoClicked().closeInventory();return;}if(e.getRawSlot()<0||e.getRawSlot()>=54||!(e.getClick()==ClickType.LEFT||e.getClick()==ClickType.RIGHT))return;Consumer<Player> action=m.actions.get(e.getRawSlot());if(action==null||m.clickPending)return;m.clickPending=true;Bukkit.getScheduler().runTask(plugin,()->{m.clickPending=false;if(menus.get(p.getUniqueId())==m&&p.getOpenInventory().getTopInventory()==m.inventory&&valid(p,m))try{action.accept(p);}catch(RuntimeException ex){p.sendMessage("Dungeon action rejected: "+ex.getMessage());}});}
 @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Menu)e.setCancelled(true);}
 @EventHandler public void closed(InventoryCloseEvent e){if(e.getInventory().getHolder() instanceof Menu m)menus.remove(m.owner,m);}
 @EventHandler public void quit(PlayerQuitEvent e){menus.remove(e.getPlayer().getUniqueId());}
 void refresh(){if(menus.isEmpty())return;cached=status();try{for(var m:new ArrayList<>(menus.values())){Player p=Bukkit.getPlayer(m.owner);if(p==null||p.getOpenInventory().getTopInventory()!=m.inventory){menus.remove(m.owner,m);continue;}if(!valid(p,m)){p.closeInventory();continue;}if(m.screen==Screen.FLOORS||m.screen==Screen.SHARED||m.screen==Screen.PRIVATE_DETAIL||m.screen==Screen.PARTY)try{render(p,m);}catch(RuntimeException e){p.closeInventory();}}}finally{cached=null;}}
}
